begin;
with j as (select * from jsonb_to_recordset($law7d0060$[{"code_id":"NK_RF","article_number":"46","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПри отсутствии или недостаточности денежных средств (драгоценных металлов) на счетах инвестиционного товарищества и цифровых рублей на его счете цифрового рубля взыскание производится за счет денежных средств (драгоценных металлов) на счетах управляющих товарищей и цифровых рублей на их счетах цифрового рубля. При этом в первую очередь взыскание обращается на денежные средства (драгоценные металлы) на счетах управляющего товарища, ответственного за ведение налогового учета, цифровые рубли на его счете цифрового рубля. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПри отсутствии или недостаточности денежных средств (драгоценных металлов) на счетах управляющих товарищей, их цифровых рублей взыскание обращается на денежные средства (драгоценные металлы) на счетах товарищей, их цифровые рубли пропорционально доле каждого из них в общем имуществе товарищей, определяемой на дату возникновения задолженности. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nВ случае изменения размера отрицательного сальдо единого налогового счета в реестре решений о взыскании задолженности размещается информация об изменении суммы задолженности, подлежащей перечислению по поручению налогового органа на перечисление суммы задолженности, по поручению налогового органа на перечисление цифровых рублей или по поручению налогового органа на перевод электронных денежных средств, в том числе в случае формирования положительного либо нулевого сальдо единого налогового счета. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПорядок ведения реестра решений о взыскании задолженности и размещения в указанном реестре решений о взыскании задолженности, поручений налоговых органов на перечисление суммы задолженности, поручений налогового органа на перечисление цифровых рублей, поручений налогового органа на перевод электронных денежных средств, а также информации об изменении суммы задолженности, подлежащей перечислению по поручению налогового органа на перечисление суммы задолженности, по поручению налогового органа на перечисление цифровых рублей или по поручению налогового органа на перевод электронных денежных средств, в том числе в случае формирования положительного либо нулевого сальдо единого налогового счета, и информации о счетах, по которым подлежат приостановлению операции в соответствии с пунктом 2 статьи 76 настоящего Кодекса, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nВ поручении налогового органа на перечисление суммы задолженности должны указываться счета налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, с которых должно быть произведено перечисление денежных средств, и сумма денежных средств, подлежащая перечислению.\n\nРазмещение поручения налогового органа на перечисление суммы задолженности, поручения налогового органа на перечисление цифровых рублей и поручения налогового органа на перевод электронных денежных средств либо информации об изменении суммы задолженности, подлежащей перечислению по поручению налогового органа на перечисление суммы задолженности, в том числе в случае формирования положительного либо нулевого сальдо, в реестре решений о взыскании задолженности признается получением банком, а в отношении цифровых рублей оператором платформы цифрового рубля таких поручений либо информации об изменении суммы задолженности. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nб уплате задолженности. Решение о взыскании, принятое после истечения указанного срока, считается недействительным и исполнению не подлежит. В этом случае налоговый орган может обратиться в суд с заявлением о взыскании задолженности с налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в размере сумм, не учитываемых в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса. Заявление может быть подано в суд в течение шести месяцев после истечения срока исполнения требования об уплате задолженности. Пропущенный по уважительной причине срок подачи заявления может быть восстановлен судом. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nРешение о взыскании доводится до сведения налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в течение шести дней после вынесения указанного решения по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. В случае невозможности передачи решения о взыскании указанными способами оно направляется по почте заказным письмом и считается полученным по истечении шести дней со дня направления заказного письма.\n\nВ случае увеличения суммы недоимки, подлежащей взысканию в соответствии с решением о взыскании, соответствующая информация доводится до сведения налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в течение шести дней после изменения в реестре решений о взыскании задолженности суммы задолженности, подлежащей перечислению по поручению налогового органа, по телекоммуникационным каналам связи или через личный кабинет налогоплательщика.\n\nИнформация об изменении суммы задолженности, подлежащей взысканию в соответствии с решением о взыскании, размещается в личном кабинете налогоплательщика одновременно с изменением в реестре решений о взыскании задолженности суммы задолженности, подлежащей перечислению по поручению налогового органа.\n\nНа период, в течение которого сумма задолженности не учитывается в совокупной обязанности, действие решения о взыскании задолженности приостанавливается до даты восстановления учета суммы задолженности в совокупной обязанности в соответствии с подпунктами 2 - 34, 5 и 6 пункта 7 статьи 113 настоящего Кодекса. При этом в случае, если в течение указанного периода формируется отрицательное сальдо единого налогового счета, налоговый орган принимает решение о взыскании задолженности в порядке, предусмотренном абзацем первым настоящего пункта. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nЕсли на момент восстановления учета суммы задолженности в совокупной обязанности в соответствии с подпунктами 2 - 34, 5 и 6 пункта 7 статьи 113 настоящего Кодекса имеется неисполненное решение о взыскании задолженности, действие которого не приостановлено в соответствии с абзацем шестым настоящего пункта, действие решения о взыскании задолженности, приостановленного на период, указанный в абзаце шестом настоящего пункта, прекращается. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nВзыскание задолженности в соответствии с абзацем первым настоящего пункта осуществляется налоговым органом путем направления решений о взыскании на бумажном носителе или в электронной форме в орган, осуществляющий открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, по месту открытия лицевого счета налогоплательщика (налогового агента) в размере, не превышающем отрицательное сальдо единого налогового счета.\n\nПри неисполнении налогоплательщиком (налоговым агентом) - организацией решения о взыскании в течение трех месяцев со дня его поступления в орган, осуществляющий открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, этот орган информирует об этом налоговый орган, который направил ему решение о взыскании, в течение десяти дней по истечении указанного срока на бумажном носителе или в электронной форме.\n\nФорма, формат и порядок направления в органы, осуществляющие открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, решения о взыскании за счет денежных средств, отраженных на лицевых счетах налогоплательщика (налогового агента) - организации, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Федеральным казначейством.\n\nФорма, формат и порядок направления уведомления о неисполнении решения о взыскании за счет денежных средств, отраженных на лицевых счетах налогоплательщика (налогового агента) органами, осуществляющими открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, налоговым органам утверждаются Федеральным казначейством по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВзыскание задолженности с валютных счетов налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится в сумме, эквивалентной сумме платежа в рублях по курсу Центрального банка Российской Федерации, установленному на дату продажи валюты. При взыскании задолженности с валютных счетов налоговый орган наряду с размещением в реестре решений о взыскании задолженности поручения налогового органа на перечисление суммы задолженности размещает в указанном реестре поручение банку на продажу не позднее следующего дня иностранной валюты налогоплательщика (налогового агента) - организации или индивидуального предпринимателя и перечисление в этот же срок денежных средств от продажи иностранной валюты в сумме подлежащей взысканию задолженности на расчетный (текущий) счет налогоплательщика (налогового агента) - организации или индивидуального предпринимателя. Расходы, связанные с продажей иностранной валюты, осуществляются за счет налогоплательщика (налогового агента) - организации или индивидуального предпринимателя.\n\nВзыскание задолженности со счетов в драгоценных металлах налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится исходя из стоимости драгоценных металлов, эквивалентной сумме платежа в рублях, которая определяется исходя из учетной цены на драгоценные металлы, установленной Центральным банком Российской Федерации на дату продажи драгоценных металлов. При взыскании задолженности со счетов в драгоценных металлах налоговый орган наряду с размещением в реестре решений о взыскании задолженности поручения налогового органа на перечисление суммы задолженности размещает в указанном реестре поручение банку на продажу не позднее следующего дня драгоценных металлов налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в размере, необходимом для исполнения поручения на перечисление суммы задолженности, и перечисление в этот же срок денежных средств от продажи драгоценных металлов на расчетный (текущий) счет налогоплательщика (налогового агента). Расходы, связанные с продажей драгоценных металлов, осуществляются за счет налогоплательщика (налогового агента).\n\nНе производится взыскание задолженности с депозитного счета (вклада в драгоценных металлах) налогоплательщика (налогового агента), если не истек срок действия депозитного договора (договора банковского вклада в драгоценных металлах).\n\nПри наличии депозитного договора налоговый орган вправе дать банку поручение на перечисление по истечении срока действия депозитного договора денежных средств с депозитного счета на расчетный (текущий) счет налогоплательщика (налогового агента) посредством его размещения в реестре решений о взыскании задолженности, если к этому времени не будет исполнено банком размещенное в реестре решений о взыскании задолженности поручение налогового органа на перечисление суммы задолженности.\n\nПри наличии договора банковского вклада в драгоценных металлах налоговый орган вправе дать банку поручение на продажу драгоценных металлов в размере, необходимом для исполнения поручения на перечисление суммы задолженности, посредством его размещения в реестре решений о взыскании задолженности по истечении срока действия указанного договора и перечисление денежных средств от продажи драгоценных металлов в сумме подлежащей взысканию задолженности на расчетный (текущий) счет налогоплательщика (налогового агента), если к этому времени не будет исполнено банком размещенное в реестре решений о взыскании задолженности поручение налогового органа на перечисление суммы задолженности.\n\nФормы и форматы поручений налоговых органов банкам на продажу иностранной валюты и драгоценных металлов налогоплательщиков (налоговых агентов) - организаций и индивидуальных предпринимателей утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации.\n\nПри недостаточности или отсутствии денежных средств (драгоценных металлов) на счетах налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в день получения банком поручения налогового органа на перечисление сумм задолженности такое поручение исполняется по мере поступления денежных средств (драгоценных металлов) на эти счета в течение одного операционного дня такого поступления на рублевые счета, в течение двух операционных дней каждого такого поступления на валютные счета, в течение двух операционных дней каждого такого поступления на счета в драгоценных металлах.\n\n10. При недостаточности или отсутствии денежных средств на счетах налогоплательщика (налогового агента) - организации или индивидуального предпринимателя налоговый орган вправе взыскать задолженность за счет электронных денежных средств.\n\nВзыскание задолженности за счет электронных денежных средств налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится путем направления в банк, в котором находятся электронные денежные средства, поручения налогового органа на перевод электронных денежных средств на счет налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в банке.\n\nПоручение налогового органа на перевод электронных денежных средств должно содержать указание реквизитов корпоративного электронного средства платежа налогоплательщика (персонифицированных электронных средств платежа) (налогового агента) - организации или индивидуального предпринимателя, с использованием которого должен быть осуществлен перевод электронных денежных средств, указание подлежащей переводу суммы, а также реквизитов счета налогоплательщика (налогового агента) - организации или индивидуального предпринимателя.\n\nВзыскание задолженности может производиться за счет остатков электронных денежных средств в рублях, а при их недостаточности за счет остатков электронных денежных средств в иностранной валюте. При взыскании задолженности за счет остатков электронных денежных средств в иностранной валюте и указании в поручении налогового органа на перевод электронных денежных средств валютного счета налогоплательщика (налогового агента) - организации или индивидуального предпринимателя банк осуществляет перевод электронных денежных средств на этот счет.\n\nПри взыскании задолженности за счет остатков электронных денежных средств в иностранной валюте и указании в поручении налогового органа на перевод электронных денежных средств с рублевого счета налогоплательщика (налогового агента) - организации или индивидуального предпринимателя руководитель (заместитель руководителя) налогового органа одновременно с поручением налогового органа на перевод электронных денежных средств направляет поручение банку на продажу не позднее следующего дня иностранной валюты налогоплательщика (налогового агента) - организации или индивидуального предпринимателя. Расходы, связанные с продажей иностранной валюты, осуществляются за счет налогоплательщика (налогового агента). Банк осуществляет перевод электронных денежных средств на рублевый счет налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в сумме, эквивалентной сумме платежа в рублях по курсу Центрального банка Российской Федерации, установленному на дату перевода электронных денежных средств.\n\nПри недостаточности или отсутствии электронных денежных средств налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в день получения банком поручения налогового органа на перевод электронных денежных средств такое поручение исполняется по мере получения электронных денежных средств.\n\nПоручение налогового органа на перевод электронных денежных средств исполняется банком не позднее одного операционного дня, следующего за днем получения им указанного поручения, если взыскание задолженности производится за счет остатков электронных денежных средств в рублях, и не позднее двух операционных дней, если взыскание налога производится за счет остатков электронных денежных средств в иностранной валюте.\n\nВзыскание задолженности за счет цифровых рублей налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится путем направления оператору платформы цифрового рубля поручения налогового органа на перечисление цифровых рублей.\n\nПоручение налогового органа на перечисление цифровых рублей должно содержать указание реквизитов счета цифрового рубля налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, с которого должно быть произведено перечисление, указание подлежащей перечислению суммы.\n\nПоручение налогового органа на перечисление цифровых рублей исполняется оператором платформы цифрового рубля не позднее одного операционного дня, следующего за днем получения им указанного поручения.\n\nПри недостаточности или отсутствии цифровых рублей налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в день получения оператором платформы цифрового рубля поручения налогового органа на перечисление цифровых рублей такое поручение исполняется по мере получения цифровых рублей.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2023 № 610-ФЗ)\n\nПоложения абзаца первого настоящего пункта применяются в отношении налогоплательщика (налогового агента) - организации при поступлении в налоговый орган уведомления органа, осуществляющего открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, о невозможности исполнения решения налогового органа о взыскании за счет денежных средств, отраженных на лицевых счетах налогоплательщика (налогового агента) - организации.\n\n14. Со дня отзыва у кредитной организации лицензии на осуществление банковских операций взыскание задолженности за счет денежных средств (драгоценных металлов) на счетах в такой кредитной организации производится с учетом положений Федерального закона \"О банках и банковской деятельности\" и Федерального закона от 26 октября 2002 го\n\nда № 127-ФЗ \"О несостоятельности (банкротстве)\".\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 46. Взыскание задолженности за счет денежных средств (драгоценных металлов) на счетах налогоплательщика (плательщика сбора, плательщика страховых взносов) - организации, индивидуального предпринимателя или налогового агента - организации, индивидуального предпринимателя в банках, а также за счет его электронных денежных средств и цифровых рублей на счетах цифрового рубля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c38ff45064d8d001905c777d600bf31100ca1845c9df45fb57728f163e8b3f01"},{"code_id":"NK_RF","article_number":"47","version_date":"2000-07-31","article_text":"1. В случае, предусмотренном пунктом 11 статьи 46 настоящего Кодекса, налоговый орган вправе взыскать задолженность за счет имущества, в том числе за счет наличных денежных средств, налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, не утратившего свой статус на дату принятия постановления о взыскании задолженности (далее в настоящей статье - индивидуальный предприниматель), в пределах сумм, не превышающих отрицательное сальдо единого налогового счета, и с учетом сумм, в отношении которых произведено взыскание в соответствии со статьей 46 настоящего Кодекса.\n\nВзыскание задолженности за счет имущества налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится на основании постановления налогового органа о взыскании задолженности налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в бюджетную систему Российской Федерации за счет имущества (далее - постановление о взыскании задолженности), размещенного в реестре решений о взыскании задолженности.\n\n2. Направление постановления о взыскании задолженности судебному приставу-исполнителю для исполнения осуществляется в порядке, предусмотренном Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", с учетом особенностей, предусмотренных настоящей статьей.\n\nОдновременно с направлением постановления о взыскании задолженности налоговый орган размещает указанное постановление в реестре решений о взыскании задолженности с указанием сведений о его отправке судебному приставу-исполнителю. При поступлении от судебного пристава-исполнителя постановления о наложении ареста и (или) постановления об обращении взыскания на денежные средства (электронные денежные средства), цифровые рубли налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, находящиеся в банке, на счете цифрового рубля, действие поручения налогового органа на перечисление соответствующей суммы задолженности, размещенного в реестре решений о взыскании задолженности в соответствии со статьей 46 настоящего Кодекса, приостанавливается до исполнения указанного постановления в полном объеме или его отмены. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n3. Направление судебному приставу и размещение постановления о взыскании задолженности в реестре решений о взыскании задолженности осуществляются в течение десяти месяцев:\n\nлибо с даты размещения в реестре решений о взыскании задолженности решения о взыскании задолженности в размере отрицательного сальдо единого налогового счета, превышающем 30 тысяч рублей;\n\nлибо с даты окончания исполнительного производства по ранее размещенному постановлению при наличии отрицательного сальдо на едином налоговом счете в размере, превышающем 30 тысяч рублей;\n\nлибо с даты возникновения после размещения в реестре решений о взыскании задолженности предшествующего постановления новой суммы задолженности на едином налоговом счете в размере, превышающем 30 тысяч рублей;\n\nлибо по истечении трех лет с даты размещения в реестре решений о взыскании задолженности решения о взыскании задолженности в размере отрицательного сальдо единого налогового счета, не превышающем 30 тысяч рублей.\n\n4. Постановление о взыскании задолженности, размещенное после истечения срока, установленного пунктом 3 настоящей статьи, исполнению не подлежит. В этом случае налоговый орган может обратиться в суд с заявлением о взыскании с налогоплательщика (налогового агента) - организации или индивидуального предпринимателя задолженности в размере сумм, не учитываемых в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса. Заявление может быть подано в суд в течение двух лет со дня истечения сроков, указанных в пункте 3 настоящей статьи. Пропущенный по уважительной причине срок подачи заявления может быть восстановлен судом.\n\nПостановление о взыскании задолженности, в отношении которой вынесен судебный акт, размещается в реестре решений о взыскании задолженности одновременно с информацией о таком судебном акте, вступившем в законную силу.\n\n5. Постановление о взыскании задолженности должно соответствовать требованиям к исполнительным документам, установленным Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", а также содержать:\n\n1) наименование налогового органа, выдавшего указанное постановление;\n\n2) дату принятия и номер решения налогового органа о взыскании задолженности;\n\n3) идентификационный номер налогоплательщика, наименование и адрес налогоплательщика (налогового агента) - организации либо фамилию, имя, отчество, паспортные данные, адрес места жительства налогоплательщика (налогового агента) - индивидуального предпринимателя, на чье имущество обращается взыскание;\n\n4) дату выдачи указанного постановления.\n\n6. Исполнительные действия должны быть совершены и требования, содержащиеся в постановлении, исполнены судебным приставом-исполнителем в двухмесячный срок со дня возбуждения соответствующего исполнительного производства.\n\n7. Взыскание задолженности за счет имущества налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится последовательно в отношении:\n\n1) наличных денежных средств, денежных средств и драгоценных металлов, за исключением счетов в банках, в отношении которых направлены поручения в соответствии со статьей 46 настоящего Кодекса;\n\n2) имущества, не участвующего непосредственно в производстве продукции (товаров), в частности ценных бумаг, валютных ценностей, непроизводственных помещений, легкового автотранспорта, предметов дизайна служебных помещений;\n\n3) готовой продукции (товаров), а также иных материальных ценностей, не участвующих и (или) не предназначенных для непосредственного участия в производстве;\n\n4) сырья и материалов, предназначенных для непосредственного участия в производстве, а также станков, оборудования, зданий, сооружений и других основных средств;\n\n5) имущества, переданного по договору во владение, в пользование или распоряжение другим лицам без перехода к ним права собственности на это имущество, если для обеспечения исполнения обязанности по уплате налога такие договоры расторгнуты или признаны недействительными в установленном порядке;\n\n6) другого имущества, за исключением предназначенного для повседневного личного пользования индивидуальным предпринимателем или членами его семьи, определяемого в соответствии с законодательством Российской Федерации.\n\n8. Взыскание задолженности в части налога, подлежащего уплате участником договора инвестиционного товарищества - управляющим товарищем, ответственным за ведение налогового учета, в связи с выполнением договора инвестиционного товарищества (за исключением налога на прибыль организаций, возникающего в связи с участием данного товарища в договоре инвестиционного товарищества) производится за счет общего имущества товарищей.\n\nПри отсутствии или недостаточности общего имущества товарищей взыскание производится за счет имущества управляющих товарищей. При этом в первую очередь взыскание обращается на имущество управляющего товарища, ответственного за ведение налогового учета.\n\nВ случае отсутствия или недостаточности имущества управляющих товарищей взыскание обращается на имущество товарищей пропорционально доле каждого из них в общем имуществе товарищей, определяемой на дату возникновения задолженности.\n\n9. В случае взыскания задолженности за счет имущества налогоплательщика (налогового агента), не являющегося денежными средствами, обязанность по уплате налога, сбора, страховых взносов, пеней, штрафов считается исполненной с момента погашения задолженности в пределах сумм денежных средств, вырученных от реализации такого имущества.\n\n10. Должностные лица налоговых органов (таможенных органов) не вправе приобретать имущество налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, реализуемое в порядке исполнения решения о взыскании задолженности за счет имущества налогоплательщика (налогового агента) - организации или индивидуального предпринимателя.\n\n11. Положения настоящей статьи применяются также при взыскании задолженности в части уплаты сборов, страховых взносов, пеней, штрафов, процентов в случаях, предусмотренных настоящим Кодексом.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 47. Взыскание задолженности за счет иного имущества налогоплательщика (налогового агента, плательщика сбора, плательщика страховых взносов) - организации, индивидуального предпринимателя","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8397fffdc7c4b8b2bee0cdfb5a363877600b30c6c67f248bfaed75198e5ae5a0"},{"code_id":"NK_RF","article_number":"48","version_date":"2000-07-31","article_text":"1. В случае неисполнения налогоплательщиком (плательщиком сбора, плательщиком страховых взносов) - физическим лицом, не являющимся индивидуальным предпринимателем (утратившим статус индивидуального предпринимателя) (далее в настоящей статье - физическое лицо), в установленный срок обязанности по уплате налога, сбора, страховых взносов, пеней, штрафов, процентов налоговый орган обращает взыскание на имущество физического лица в размере, не превышающем отрицательное сальдо единого налогового счета, посредством размещения в реестре решений о взыскании задолженности в соответствии со статьями 46 и 47 настоящего Кодекса решения о взыскании задолженности, поручения налогового органа на перечисление суммы задолженности, информации о счетах, по которым подлежат приостановлению операции в соответствии с пунктом 2 статьи 76 настоящего Кодекса, постановления о взыскании задолженности.\n\nК решениям о взыскании задолженности, поручениям на перечисление суммы задолженности, информации о счетах, по которым подлежат приостановлению операции, и постановлениям о взыскании задолженности, указанным в настоящей статье, применяются правила, предусмотренные статьями 46, 47 и 76 настоящего Кодекса, если иное не предусмотрено настоящей статьей.\n\n2. В целях настоящей статьи принятие решения о взыскании задолженности и его направление физическому лицу осуществляются в течение шести месяцев с даты истечения срока исполнения требования об уплате задолженности.\n\nРешение о взыскании задолженности, принятое после истечения указанного срока, считается недействительным и исполнению не подлежит. В этом случае налоговый орган может обратиться в суд с административным исковым заявлением о взыскании задолженности в размере сумм, не учитываемых в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса, в течение шести месяцев после истечения срока, установленного абзацем первым настоящего пункта для принятия решения о взыскании задолженности. Пропущенный по уважительной причине срок подачи административного искового заявления может быть восстановлен судом.\n\nРешение о взыскании задолженности направляется физическому лицу через личный кабинет налогоплательщика или через личный кабинет на едином портале государственных и муниципальных услуг. В случае невозможности передачи указанными способами такое решение направляется по почте заказным письмом.\n\nФизическому лицу информация об увеличении суммы задолженности, подлежащей взысканию в соответствии с решением о взыскании задолженности, направляется в электронной форме через личный кабинет налогоплательщика или личный кабинет на едином портале государственных и муниципальных услуг в течение шести дней после изменения в реестре решений о взыскании задолженности суммы задолженности, подлежащей перечислению по поручению налогового органа.\n\n3. Взыскание задолженности за счет имущества физического лица производится последовательно в отношении:\n\n1) денежных средств на счетах в банке и электронных денежных средств, переводы которых осуществляются с использованием персонифицированных электронных средств платежа, драгоценных металлов на счетах (во вкладах) в банке, цифровых рублей;\n\n2) наличных денежных средств;\n\n3) имущества, переданного по договору во владение, в пользование или распоряжение другим лицам без перехода к ним права собственности на это имущество, если для обеспечения исполнения обязанности по уплате налога, сбора, страховых взносов, пеней, штрафов, процентов такой договор расторгнут или признан недействительным в установленном порядке;\n\n4) другого имущества, за исключением предназначенного для повседневного личного пользования физическим лицом или членами его семьи, определяемого в соответствии с законодательством Российской Федерации.\n\n4. Взыскание задолженности за счет имущества физического лица, которое производится в отношении денежных средств на счетах в банке и электронных денежных средств, переводы которых осуществляются с использованием персонифицированных электронных средств платежа, драгоценных металлов на счетах (во вкладах) в банке, цифровых рублей, осуществляется налоговым органом посредством размещения по истечении семи дней со дня направления физическому лицу решения о взыскании задолженности соответствующего поручения налогового органа на перечисление суммы задолженности и информации о счетах, по которым подлежат приостановлению операции в соответствии с пунктом 2 статьи 76 настоящего Кодекса, в реестре решений о взыскании задолженности. Поручение налогового органа на перечисление суммы задолженности и приостановление операций по счетам исполняются банком (а в отношении цифровых рублей - оператором платформы цифрового рубля) в соответствии со статьей 46 настоящего Кодекса с применением порядка, предусмотренного законодательством Российской Федерации об исполнительном производстве и нормами федеральных законов, регулирующими условия и порядок принудительного исполнения судебных актов, актов других органов и должностных лиц, для обращения взыскания на денежные средства по исполнительному документу. При этом:\n\n1) при исполнении банком поручения налогового органа на перечисление суммы задолженности и приостановления операций по счетам не допускается обращение взыскания на виды доходов, в отношении которых установлены ограничения размера удержания и (или) на которые не может быть обращено взыскание в соответствии со статьями 99 и 101 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\";\n\n2) физическое лицо вправе обратиться в банк, исполняющий поручение налогового органа на перечисление суммы задолженности с его счета и приостановление операций по счетам, с заявлением о сохранении заработной платы и иных доходов ежемесячно в порядке и на условиях, которые предусмотрены статьей 8 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\" для исполнения содержащихся в исполнительном документе требований о взыскании денежных средств;\n\n3) поручение налогового органа на перечисление суммы задолженности и приостановление операций по счетам не действуют в отношении специальных избирательных счетов, специальных счетов фондов референдума и иных счетов в части сумм денежных средств, право собственности на которые не принадлежит владельцу соответствующего счета и на которые в соответствии с законодательством Российской Федерации не может быть обращено взыскание по обязательствам владельца этого счета.\n\n5. При неисполнении (частичном неисполнении) поручения налогового органа на перечисление суммы задолженности и при наличии отрицательного сальдо единого налогового счета налоговый орган для взыскания задолженности за счет иного имущества физического лица направляет судебному приставу-исполнителю и одновременно размещает в реестре решений о взыскании задолженности постановление о взыскании задолженности в порядке и сроки, которые установлены статьей 47 настоящего Кодекса.\n\n6. Денежные средства, поступившие в счет исполнения обязанности по уплате налога, сбора, страховых взносов, пеней, штрафов, процентов в соответствии с настоящей статьей, учитываются в качестве единого налогового платежа и определяются по принадлежности в соответствии со статьей 45 настоящего Кодекса.\n\n7. Должностные лица налоговых органов (таможенных органов) не вправе приобретать имущество физического лица, реализуемое в порядке взыскания налога, сбора, страховых взносов, пеней, штрафов, процентов за счет имущества физического лица.\n\n8. Для применения мер взыскания в соответствии с настоящей статьей в отношении задолженности в размере сумм, не учитываемых в совокупной обязанности в соответствии с подпунктом 101 пункта 5, подпунктами 31 - 33 пункта 7 статьи 113 настоящего Кодекса, налоговый орган обращается в суд с административным исковым заявлением (далее - административное исковое заявление о взыскании задолженности) в следующих случаях:\n\n1) если физическим лицом в течение тридцати дней со дня формирования налоговым органом сообщения об отказе в перерасчете суммы ранее исчисленного налога подана жалоба в отношении сумм налогов, указанных в налоговом уведомлении, либо со дня принятия решения вышестоящего налогового органа об оставлении без удовлетворения жалобы на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, представлено уведомление о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении. В случае пропуска по уважительной причине срока, предусмотренного настоящим подпунктом, этот срок может быть восстановлен налоговым органом по ходатайству физического лица, подаваемому одновременно с жалобой в отношении сумм налогов, указанных в налоговом уведомлении (уведомлением о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении), если обязанность по уплате соответствующих сумм налогов не исполнена на дату подачи такого ходатайства. По результатам рассмотрения ходатайства о восстановлении пропущенного срока, указанного в настоящем подпункте, налоговый орган выносит решение, которое не позднее трех дней со дня получения такого ходатайства направляется физическому лицу в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо на бумажном носителе через многофункциональный центр предоставления государственных и муниципальных услуг или по почте заказным письмом;\n\n2) если физическим лицом подана жалоба (апелляционная жалоба) на решение о привлечении к ответственности за совершение налогового правонарушения (решение об отказе в привлечении к ответственности за совершение налогового правонарушения), решение об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично.\n\n9. Уведомление о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, представляется в налоговый орган, направивший налоговое уведомление.\n\nФорма и формат уведомления о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nУведомление о несогласии с решением вышестоящего налог\n\nового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, может быть представлено физическим лицом в налоговый орган лично или через представителя либо направлено в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо на бумажном носителе через многофункциональный центр предоставления государственных и муниципальных услуг или по почте заказным письмом.\n\n10. В случаях, предусмотренных пунктом 8 настоящей статьи, налоговый орган обращается в суд с административным исковым заявлением о взыскании задолженности в течение шести месяцев:\n\n1) со дня принятия налоговым органом решения по жалобе в отношении сумм налогов, указанных в налоговом уведомлении, поданной в течение тридцати дней со дня формирования сообщения об отказе в перерасчете сумм ранее исчисленного налога, либо со дня представления физическим лицом уведомления о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, в течение тридцати дней со дня принятия решения вышестоящего налогового органа об оставлении такой жалобы без удовлетворения, если размер задолженности превышает три тысячи рублей;\n\n2) со дня принятия налоговым органом решения по жалобе (апелляционной жалобе) на решение о привлечении к ответственности за совершение налогового правонарушения (решение об отказе в привлечении к ответственности за совершение налогового правонарушения), решение об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично, если размер задолженности превышает три тысячи рублей;\n\n3) со дня превышения общей суммы задолженности, подлежащей взысканию в судебном порядке, трех тысяч рублей;\n\n4) по истечении трех лет с наиболее ранней даты принятия налоговым органом решения по жалобе в отношении сумм налогов, указанных в налоговом уведомлении, поданной в течение тридцати дней со дня формирования сообщения об отказе в перерасчете суммы ранее исчисленного налога, либо с наиболее ранней даты представления физическим лицом уведомления о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, в течение тридцати дней со дня принятия решения вышестоящего налогового органа об оставлении такой жалобы без удовлетворения, если общая сумма задолженности, подлежащая взысканию в судебном порядке, не превысила трех тысяч рублей;\n\n5) по истечении трех лет с наиболее ранней даты принятия налоговым органом решения по жалобе (апелляционной жалобе) на решение о привлечении к ответственности за совершение налогового правонарушения (решение об отказе в привлечении к ответственности за совершение налогового правонарушения), решение об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично, если общая сумма задолженности, подлежащая взысканию в судебном порядке, не превысила трех тысяч рублей.\n\n11. К административному исковому заявлению о взыскании задолженности может прилагаться ходатайство налогового органа о применении мер предварительной защиты.\n\nПропущенный по уважительной причине срок подачи административного искового заявления о взыскании задолженности может быть восстановлен судом.\n\n12. В случае исполнения физическим лицом обязанности по уплате соответствующих сумм задолженности, не учитываемых в совокупной обязанности в соответствии с подпунктом 101 пункта 5, подпунктами 31 - 33 пункта 7 статьи 113 настоящего Кодекса, положения пунктов 8 - 11 настоящей статьи не применяются.\n\n13. Действие правил, предусмотренных настоящей статьей, также распространяется на налоговых агентов - физических лиц, утративших статус индивидуального предпринимателя на дату принятия решения о взыскании задолженности или являющихся нотариусами, занимающимися частной практикой, адвокатами, учредившими адвокатские кабинеты, и другими лицами, занимающимися в установленном законодательством Российской Федерации порядке частной практикой.\n\n(Статья в редакции  Федерального закона от 31.07.2025 № 287-ФЗ)","article_title":"Статья 48. Взыскание задолженности за счет имущества налогоплательщика (плательщика сборов, плательщика страховых взносов) - физического лица, не являющегося индивидуальным предпринимателем","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fae62c573d02b335acaa2362867683d7fac26e3fe832779127003617e5b60904"},{"code_id":"NK_RF","article_number":"49","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 49. Исполнение обязанности по уплате налогов, сборов, страховых взносов (пеней, штрафов) при ликвидации организации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e8f7509e9e7b22a0adb706c8d845d8a5a06f61adaf6afdb69ec5c68318dcbe3"},{"code_id":"NK_RF","article_number":"5","version_date":"2000-07-31","article_text":"1. Акты законодательства о налогах вступают в силу не ранее чем по истечении одного месяца со дня их официального опубликования и не ранее 1-го числа очередного налогового периода по соответствующему налогу, за исключением случаев, предусмотренных настоящей статьей.\n\nАкты законодательства о сборах вступают в силу не ранее чем по истечении одного месяца со дня их официального опубликования, за исключением случаев, предусмотренных настоящей статьей.\n\nАкты законодательства о налогах и сборах в части регулирования страховых взносов вступают в силу не ранее чем по истечении одного месяца со дня их официального опубликования и не ранее 1-го числа очередного расчетного периода по страховым взносам, за исключением случаев, предусмотренных настоящей статьей. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ)\n\nФедеральные законы, вносящие изменения в настоящий Кодекс в части установления новых налогов (за исключением специальных налоговых режимов) и (или) сборов, а также акты законодательства о налогах и сборах субъектов Российской Федерации, нормативные правовые акты представительных органов муниципальных образований, нормативные правовые акты представительного органа федеральной территории \"Сириус\", вводящие налоги, вступают в силу не ранее 1 января года, следующего за годом их принятия, но не ранее одного месяца со дня их официального опубликования. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ, от 27.07.2006 № 137-ФЗ, от 11.06.2021 № 199-ФЗ, от 25.02.2022 № 18-ФЗ)\n\nАкты законодательства о налогах и сборах, указанные в пунктах 3 и 4 настоящей статьи, могут вступать в силу в сроки, прямо предусмотренные этими актами, но не ранее даты их официального опубликования. (Дополнение абзацем - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\nдаты утраты налогоплательщиком статуса участника специального инвестиционного контракта;\n\nдаты окончания сроков действия налоговых ставок, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения специального инвестиционного контракта, если дата окончания сроков действия налоговых ставок,  налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения специального инвестиционного контракта, наступает ранее даты утраты налогоплательщиком статуса налогоплательщика - участника специального инвестиционного контракта. (В редакции Федерального закона от 02.08.2019 № 269-ФЗ)\n\nПоложения настоящего пункта распространяются на акты законодательства о налогах и сборах в части налога на прибыль организаций, налога на имущество организаций, транспортного налога, земельного налога и применяются для налогоплательщика - участника специального инвестиционного контракта при условии указания в соответствующем специальном инвестиционном контракте ссылок на положения актов законодательства о налогах и сборах в части пониженных налоговых ставок или налоговых льгот и иных преференций (включая особый порядок и сроки уплаты, порядок исчисления налогов и сборов), установленных для налогоплательщиков - участников специальных инвестиционных контрактов в связи с выполнением ими специального инвестиционного контракта, на которые распространяется действие настоящего пункта. (В редакции Федерального закона от 02.08.2019 № 269-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 23.05.2016 № 144-ФЗ) (В редакции Федерального закона от 03.08.2018 № 300-ФЗ)\n\nдаты утраты налогоплательщиком статуса соответственно резидента территории опережающего развития, резидента свободного порта Владивосток или резидента особой экономической зоны;\n\nдаты окончания сроков действия налоговых ставок, тарифов  страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения соглашения об осуществлении деятельности, указанного в абзаце первом настоящего пункта, если дата окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения такого соглашения, наступает ранее даты утраты налогоплательщиком статуса резидента территории опережающего развития, резидента свободного порта Владивосток или резидента особой экономической зоны.\n\nПоложения настоящего пункта распространяются на акты законодательства о налогах и сборах в части страховых взносов, налога на прибыль организаций, налога на имущество организаций, транспортного налога, земельного налога и применяются для налогоплательщика - резидента территории опережающего развития, резидента свободного порта Владивосток и резидента особой экономической зоны при условии указания в соответствующем соглашении об осуществлении деятельности ссылок на положения актов законодательства о налогах и сборах в части пониженных налоговых ставок, тарифов страховых взносов или налоговых льгот и иных преференций (включая особый порядок и сроки уплаты, порядок исчисления налогов и сборов), установленных для налогоплательщиков - резидентов территорий опережающего развития, налогоплательщиков - резидентов свободного порта Владивосток и налогоплательщиков - резидентов особых экономических зон в связи с исполнением ими соглашений об осуществлении деятельности, на которые распространяется действие настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 300-ФЗ) (В редакции  Федерального закона от 02.11.2023 № 522-ФЗ)\n\nВ отношении налогоплательщиков, являющихся стороной соответствующего соглашения о защите и поощрении капиталовложений, заключенного с субъектом Российской Федерации, не применяются положения последующих актов законодательства о налогах и сборах в части изменения порядка определения налоговой базы, налоговых ставок, налоговых льгот, порядка и (или) сроков уплаты по налогу на имущество организаций и транспортному налогу.\n\nВ отношении налогоплательщиков (плательщиков сборов), являющихся стороной соответствующего соглашения о защите и поощрении капиталовложений, заключенного с Российской Федерацией и субъектом Российской Федерации, не применяются положения последующих актов законодательства о налогах и сборах в части изменений, указанных в абзаце втором настоящего пункта, а также в части изменения объекта налогообложения, порядка определения налоговой базы, налогового периода, налоговых ставок, порядка исчисления, порядка и (или) сроков уплаты по налогу на прибыль организаций, изменения сроков уплаты и (или) порядка возмещения налога на добавленную стоимость и (или) введения новых налогов и (или) сборов.\n\nВ отношении налогоплательщиков, являющихся стороной соответствующего соглашения о защите и поощрении капиталовложений, заключенного с субъектом Российской Федерации и муниципальным образованием, не применяются положения последующих актов законодательства о налогах и сборах в части изменений, указанных в абзаце втором настоящего пункта, а также в части изменения налоговых ставок, налоговых льгот, порядка и (или) сроков уплаты по земельному налогу.\n\nВ отношении налогоплательщиков (плательщиков сборов), являющихся стороной соответствующего соглашения о защите и поощрении капиталовложений, заключенного с Российской Федерацией, субъектом Российской Федерации и муниципальным образованием, не применяются положения последующих актов законодательства о налогах и сборах в части изменений, указанных в абзацах втором - четвертом настоящего пункта.\n\nВ отношении налогоплательщика, являющегося стороной соглашения о защите и поощрении капиталовложений, одной из сторон которого также является Российская Федерация, и реализующего новый инвестиционный проект в сфере добычи руд цветных металлов (золота) с объемом капитальных вложений не менее 300 миллиардов рублей, включенного в реестр участников региональных инвестиционных проектов, не применяются положения последующих актов законодательства о налогах и сборах в части изменения или отмены порядка определения и применения коэффициента, характеризующего территорию добычи полезного ископаемого, при исчислении налога на добычу полезных ископаемых. (Дополнение абзацем - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\nОсобенности применения актов законодательства о налогах и сборах, предусмотренные настоящим пунктом, не распространяются на последующие акты законодательства о налогах и сборах, устанавливающие налоговые льготы по налогу на имущество организаций, транспортному и земельному налогам, условия и сроки применения и прекращения действия указанных льгот.\n\nПоложения настоящего пункта применяются в отношении указанных налогоплательщиков (плательщиков сборов) до наступления наиболее ранней из следующих дат:\n\nдаты истечения указанного в реестре срока применения стабилизационной оговорки, установленного соответствующим соглашением о защите и поощрении капиталовложений в соответствии с частями 10 и 11 статьи 10 Федерального закона \"О защите и поощрении капиталовложений в Российской Федерации\";\n\nдаты включения сведений о расторжении соответствующего соглашения о защите и поощрении капиталовложений в реестр.\n\nЕсли иное не предусмотрено настоящим пунктом, положения настоящего пункта применяются в отношении налогоплательщиков (плательщиков сборов) при условии ведения ими раздельного учета объектов налогообложения, налоговой базы и сумм налогов по налогам, подлежащим уплате при исполнении соглашений о защите и поощрении капиталовложений, указанных в абзацах втором - пятом настоящего пункта, и при осуществлении иной хозяйственной деятельности, а также раздельного учета доходов (расходов), полученных (понесенных) при исполнении соглашений, указанных в абзацах третьем и пятом настоящего пункта, и доходов (расходов), полученных (понесенных) при осуществлении иной хозяйственной деятельности.\n\nНалогоплательщик (плательщик сбора), являющийся стороной соглашения о защите и поощрении капиталовложений, в соответствии с Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" признаваемый проектной компанией, раздельный учет, предусмотренный абзацем одиннадцатым настоящего пункта: (В редакции  Федерального закона от 28.06.2022 № 225-ФЗ)\n\nвправе не вести в случае, если он не является одновременно участником консолидированной группы налогоплательщиков;\n\nведет в части, касающейся соблюдения им положений пункта 9 статьи 2781 настоящего Кодекса, в случае, если он одновременно является участником консолидированной группы налогоплательщиков.\n\n(Дополнение пунктом - Федеральный закон от 01.04.2020 № 70-ФЗ)\n\nдаты утраты налогоплательщиком статуса международной холдинговой компании;\n\nдаты окончания установленного на дату приобретения международной компанией (организацией, указанной в пункте 11 статьи 242 настоящего Кодекса) статуса международной холдинговой компании в соответствии со статьей 242 настоящего Кодекса срока действия:\n\nналоговых ставок;\n\nпорядка исчисления налогов;\n\nпорядка исчисления налоговых баз.\n\nПоложения актов законодательства субъектов Российской Федерации о налогах и сборах в части налога на имущество организаций и транспортного налога в случае, если такие положения вступили в силу после даты приобретения международной компанией (организацией, указанной в пункте 11 статьи 242 настоящего Кодекса) статуса международной х\n\nолдинговой компании и предусматривают увеличение и (или) отмену пониженных налоговых ставок, а также изменение условий применения указанных налоговых ставок, не применяются в отношении налогоплательщика, признаваемого международной холдинговой компанией в соответствии со статьей 242 настоящего Кодекса, до наступления наиболее ранней из следующих дат:\n\nдаты утраты налогоплательщиком статуса международной холдинговой компании;\n\nдаты окончания установленного на дату приобретения международной компанией (организацией, указанной в пункте 11 статьи 242 настоящего Кодекса) статуса международной холдинговой компании в соответствии со статьей 242 настоящего Кодекса срока действия:\n\nналоговых ставок;\n\nусловий применения указанных налоговых ставок.\n\n(Дополнение пунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nдаты утраты налогоплательщиком (плательщиком страховых взносов) статуса участника свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях; (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nдаты окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, если дата окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения указанного договора, наступает ранее даты утраты налогоплательщиком (плательщиком страховых взносов) статуса участника свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nПоложения настоящего пункта распространяются на акты законодательства о налогах и сборах в части страховых взносов, налога на прибыль организаций, налога на имущество организаций, земельного налога и применяются для налогоплательщика (плательщика страховых взносов) - участника свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях при условии указания в соответствующем договоре об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях ссылок на положения актов законодательства о налогах и сборах в части пониженных налоговых ставок, тарифов страховых взносов или налоговых льгот и иных преференций (включая особый порядок и сроки уплаты, порядок исчисления налогов), установленных для налогоплательщиков (плательщиков страховых взносов) - участников свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях в связи с исполнением ими договоров об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, на которые распространяется действие настоящего пункта. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 24.06.2023 № 268-ФЗ)\n\nдаты исключения резидента из единого реестра резидентов Особой экономической зоны в Калининградской области (далее в настоящем пункте - реестр);\n\nдаты окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату включения юридического лица в реестр, если дата окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату включения юридического лица в реестр, наступает ранее даты исключения резидента из реестра.\n\nПоложения настоящего пункта распространяются на акты законодательства о налогах и сборах в части страховых взносов, налога на прибыль организаций, налога на имущество организаций, земельного налога и применяются в отношении резидента в части правоотношений, связанных с реализацией инвестиционного проекта в соответствии с Федеральным законом от 10 января 2006 года № 16-ФЗ \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", при условии ведения им раздельного учета доходов (расходов), имущества, объектов налогообложения, полученных (произведенных, созданных, приобретенных) при реализации инвестиционного проекта в соответствии с Федеральным законом от 10 января 2006 года № 16-ФЗ \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", и доходов (расходов), имущества, объектов налогообложения, полученных (произведенных, созданных, приобретенных) при осуществлении иной хозяйственной деятельности.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2025 № 373-ФЗ)\n\nНормативные правовые акты, предусматривающие утверждение новых форм (форматов) налоговых деклараций (расчетов) или внесение изменений в действующие формы (форматы) налоговых деклараций (расчетов), вступают в силу не ранее чем по истечении двух месяцев со дня их официального опубликования.\n\n(Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (В редакции Федерального закона от 01.05.2016 № 130-ФЗ)","article_title":"Статья 5. Действие актов законодательства о налогах и сборах во времени","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46e7516bf7b1a43a8f465a9e315b48a9207dbadaa9c84b18e59f2219f7757a6d"},{"code_id":"NK_RF","article_number":"50","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n1. Обязанность по уплате налогов реорганизованного юридического лица исполняется его правопреемником (правопреемниками) в порядке, установленном настоящей статьей.\n\nНа правопреемника (правопреемников) реорганизованного юридического лица возлагается также обязанность по уплате причитающихся сумм штрафов, наложенных на юридическое лицо за совершение налоговых правонарушений до завершения его реорганизации. Правопреемник (правопреемники) реорганизованного юридического лица при исполнении возложенных на него настоящей статьей обязанностей по уплате налогов и сборов пользуется всеми правами, исполняет все обязанности в порядке, предусмотренном настоящим Кодексом для налогоплательщиков. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nЕсли разделительный баланс не позволяет определить долю правопреемника реорганизованного юридического лица либо исключает возможность исполнения в полном объеме обязанностей по уплате налогов каким-либо правопреемником, и такая реорганизация была направлена на неисполнение обязанностей по уплате налогов, то по решению суда вновь возникшие юридические лица могут солидарно исполнять обязанность по уплате налогов реорганизованного лица. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n11. Правила, предусмотренные настоящей статьей, применяются также в следующих случаях:\n\n1) при исполнении обязанности по уплате сбора, страховых взносов при реорганизации юридического лица;\n\n2) при определении правопреемника (правопреемников) иностранной организации, реорганизованной в соответствии с законодательством иностранного государства;\n\n3) при уплате налогов в связи с перемещением товаров через таможенную границу Евразийского экономического союза;\n\n4) при исполнении обязанности налогового агента при реорганизации юридического лица; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n5) при определении принадлежности прав и обязанностей иностранной организации, зарегистрированной в едином государственном реестре юридических лиц со статусом международной компании в порядке, предусмотренном Федеральным законом от 3 августа 2018 года № 290-ФЗ \"О международных компаниях и международных фондах\". (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)","article_title":"Статья 50. Исполнение обязанности по уплате налогов, сборов, страховых взносов (пеней, штрафов) при реорганизации юридического лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8bf8aab1f5e77c5ff813c303dd370fff5a473ac303d698c06314c30ecd784fe3"}]$law7d0060$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
